using ModConfigEnhance.Overview;
using Newtonsoft.Json;
int n=0;void Check(bool ok,string why){if(!ok)throw new Exception(why);n++;}
string home=Path.Combine(AppContext.BaseDirectory,"s-"+Guid.NewGuid().ToString("N"));string source=Path.Combine(home,"signed");Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"intro.md"),"original introduction");
var original=new OverviewProfile{id="author:fixture",name="Original preset",directory=source,readOnly=true,kind=OverviewProfileKind.Author,config=new(){values=new(){new(){pluginGuid="mod",configFile="mod.cfg",section="S",key="Key",serializedValue="1"}}}};
File.WriteAllText(Path.Combine(source,"release.json"),"{\"signed\":true}");File.WriteAllText(Path.Combine(source,"profile.json"),JsonConvert.SerializeObject(original));File.WriteAllText(Path.Combine(source,"config-values.json"),JsonConvert.SerializeObject(original.config));
var signedFiles=new Newtonsoft.Json.Linq.JArray();foreach(string path in Directory.GetFiles(source).OrderBy(p=>Path.GetFileName(p),StringComparer.Ordinal))signedFiles.Add(new Newtonsoft.Json.Linq.JObject{["path"]=Path.GetFileName(path),["sha256"]=Convert.ToBase64String(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(path)))});using(var rsa=System.Security.Cryptography.RSA.Create()){var key=rsa.ExportParameters(false);File.WriteAllText(Path.Combine(source,"signature.json"),new Newtonsoft.Json.Linq.JObject{["algorithm"]="RSA-SHA256-PKCS1",["publicKey"]=new Newtonsoft.Json.Linq.JObject{["Exponent"]=Convert.ToBase64String(key.Exponent!),["Modulus"]=Convert.ToBase64String(key.Modulus!)},["files"]=signedFiles,["signature"]=Convert.ToBase64String(rsa.SignData(System.Text.Encoding.UTF8.GetBytes(signedFiles.ToString(Newtonsoft.Json.Formatting.None)),System.Security.Cryptography.HashAlgorithmName.SHA256,System.Security.Cryptography.RSASignaturePadding.Pkcs1))}.ToString());}MCE.UpdateWorker.PackSignature.Verify(source);Check(true,"author fixture accepted by production signature verifier");
var store=new OverviewProfileStore(Path.Combine(home,"profiles"),original);var working=store.BeginAuthorEditing(original.id);
Check(working.id==original.id&&!working.readOnly&&working.directory!=source,"local working preset retains identity, not signed directory");
Check(File.Exists(Path.Combine(working.directory,"profile.json"))&&File.Exists(Path.Combine(working.directory,"config-values.json")),"local baseline pair exists before first edit");
MCE.UpdateWorker.PackSignature.Verify(source);Check(File.ReadAllText(Path.Combine(source,"intro.md"))=="original introduction","signed input and media remain unchanged after local workspace creation");
Check(store.NeedsOriginalPresetSaveChoice(original.id),"unconfirmed local working preset still prompts on first save");
var reopened=new OverviewProfileStore(store.RootDirectory,original);var reference=reopened.GetRequired(original.id);Check(reference.directory==working.directory&&!reference.readOnly,"index retains local workspace across store restart");
reopened.ConfirmOriginalPresetSave(original.id);Check(!reopened.NeedsOriginalPresetSaveChoice(original.id),"explicit first-save choice persists");
reference.config.values[0].serializedValue="2";var baseline=reopened.GetOriginalPreset(original.id);Check(baseline.config.values.Single().serializedValue=="1","edited working generation preserves original configuration baseline");baseline.config.values[0].serializedValue="9";Check(reopened.GetOriginalPreset(original.id).config.values[0].serializedValue=="1","restoration callers cannot mutate retained baseline");
reopened.Persist(reference);var third=new OverviewProfileStore(store.RootDirectory,original);var saved=third.GetRequired(original.id);Check(saved.config.values[0].serializedValue=="2"&&File.ReadAllText(Path.Combine(saved.directory,"intro.md"))=="original introduction","local preset save and reopen preserve changed parameters and copied media");string exported=ConfigurationPresetFile.Export(new[]{saved},Path.Combine(home,"export"));var imported=ConfigurationPresetFile.Read(Directory.GetFiles(exported,"*.mceconfig.json").Single());Check(imported.config.values[0].serializedValue=="2"&&!Directory.GetFiles(exported).Any(p=>p.EndsWith(".md")),"saved author-derived preset exports and reimports without media");MCE.UpdateWorker.PackSignature.Verify(source);Check(third.GetOriginalPreset(original.id).config.values[0].serializedValue=="1","signature and retained original survive edit/save/reopen/export/import roundtrip");
Console.WriteLine($"PASS {n} signed-author/configuration roundtrip checks (store persistence adapter)");
namespace ModConfigEnhance.Overview{
internal static class PublicationFilePolicy{internal static bool ProfileConfigPath(string path)=>path.EndsWith(".cfg");}internal sealed class OverviewState{}internal static class OverviewProfileExport{internal static string PortableId(string id)=>id.Replace(':','_');}
internal sealed partial class OverviewProfileStore{
private readonly object _gate=new();private Dictionary<string,OverviewProfile> _index=new();private readonly Dictionary<string,OverviewProfile> _loaded=new();internal string RootDirectory{get;}
internal OverviewProfileStore(string root,OverviewProfile original){RootDirectory=root;Directory.CreateDirectory(root);_index=File.Exists(Path.Combine(root,"index.json"))?ReadIndex():new(){[original.id]=Clone(original)};}
internal OverviewProfile GetRequired(string id){if(_loaded.TryGetValue(id,out var found))return found;var reference=Clone(_index[id]);string file=Path.Combine(reference.directory,"profile.json");if(!reference.readOnly&&File.Exists(file))reference=DeserializeJson<OverviewProfile>(File.ReadAllText(file));return _loaded[id]=reference;}
internal bool IsPackConfiguration(OverviewProfile p)=>p.id.StartsWith("author:");private static T Clone<T>(T value)=>JsonConvert.DeserializeObject<T>(JsonConvert.SerializeObject(value))!;internal static T DeserializeJson<T>(string s)=>JsonConvert.DeserializeObject<T>(s)!;
private void SaveFiles(OverviewProfile p){Directory.CreateDirectory(p.directory);AtomicWrite(Path.Combine(p.directory,"profile.json"),JsonConvert.SerializeObject(p));AtomicWrite(Path.Combine(p.directory,"config-values.json"),JsonConvert.SerializeObject(p.config));_loaded[p.id]=p;}
internal void Persist(OverviewProfile p){SaveFiles(p);UpsertReference(p);SaveIndex();}private void UpsertReference(OverviewProfile p)=>_index[p.id]=Clone(p);private void SaveIndex()=>AtomicWrite(Path.Combine(RootDirectory,"index.json"),JsonConvert.SerializeObject(_index));private Dictionary<string,OverviewProfile> ReadIndex()=>DeserializeJson<Dictionary<string,OverviewProfile>>(File.ReadAllText(Path.Combine(RootDirectory,"index.json")));
private static void AtomicWrite(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,text);}private static void CopyResources(string source,string target){foreach(string file in Directory.GetFiles(source)){File.Copy(file,Path.Combine(target,Path.GetFileName(file)),false);}}
}
